import { Component, Suspense, lazy, useEffect, useState } from 'react';
import Sprite from '../pixel/Sprite';
import { BIOMES } from '../pixel/art';
import { pixelSoundUrl, pixelVideoUrl } from '../pixel/media';
import { DEMOS } from './demos';
import { injectProps } from './injectProps';
import { THEMED_CHILDREN, THEMED_PROPS } from './theme';

// Generated by scripts/import-reactbits.mjs. Components and their sources are lazy chunks,
// so the 218 entries (several pulling in three.js / ogl / gsap) only load when their page opens.
// The catalog is local-only (its license forbids redistribution) and git-ignored, so public
// builds have no src/reactbits at all: then the glob finds nothing and the app shows Bits Lab only.
const data = Object.values(import.meta.glob('../reactbits/catalog.json', { eager: true, import: 'default' }))[0] ?? { categories: {}, items: [] };
const modules = import.meta.glob('../reactbits/*/*.jsx');
const sources = import.meta.glob('../reactbits/*/*.{jsx,js,css}', { query: '?raw', import: 'default' });

export const REACTBITS_CATEGORIES = Object.entries(data.categories).map(([slug, name]) => ({ slug, name }));

class PreviewBoundary extends Component {
  state = { error: null };

  static getDerivedStateFromError(error) {
    return { error };
  }

  render() {
    if (!this.state.error) return this.props.children;
    return (
      <div className="preview-error">
        <strong>This one needs more setup than our stage can craft.</strong>
        <span>{String(this.state.error.message ?? this.state.error)}</span>
        <span>The full source and usage are still in the loot below.</span>
      </div>
    );
  }
}

const lazyCache = new Map();

function lazyComponent(item) {
  if (!lazyCache.has(item.name)) {
    const load = modules[`../reactbits/${item.name}/${item.entry}`];
    lazyCache.set(
      item.name,
      lazy(() => load().then(mod => ({ default: mod.default ?? mod[item.name] })))
    );
  }
  return lazyCache.get(item.name);
}

function renderChildren(children, fill) {
  if (!children) return undefined;
  if (children.text) return children.text;
  const card = (
    <div className="rb-placeholder">
      <Sprite name="chest" size={48} />
      <span>Loot</span>
    </div>
  );
  // Full-bleed wrappers (cursor effects, spotlights) get the card centered over the stage;
  // others size themselves from their children, so the card stays in flow.
  return fill ? <div className="rb-placeholder-area">{card}</div> : card;
}

const pixels = value => (typeof value === 'number' ? value : /^\d+(\.\d+)?px$/.test(String(value)) ? parseFloat(value) : null);

// Reproduce the usage snippet's wrapper when it fixes a width, or a height the stage can hold
// (taller wrappers on full-bleed backgrounds would only be cropped).
const keepWrapper = wrapper => wrapper && (pixels(wrapper.width) !== null || (pixels(wrapper.height) ?? Infinity) <= 460);

// Generated video/sound for props whose demo pointed at a local media file.
function useDemoMedia(media) {
  const [urls, setUrls] = useState({});
  useEffect(() => {
    let live = true;
    for (const [name, kind] of Object.entries(media)) {
      (kind === 'video' ? pixelVideoUrl() : pixelSoundUrl()).then(url => live && setUrls(prev => ({ ...prev, [name]: url })));
    }
    return () => {
      live = false;
    };
  }, [media]);
  return urls;
}

function Preview({ item, props }) {
  const Comp = lazyComponent(item);
  const demo = DEMOS[item.name] ?? {};
  const mediaUrls = useDemoMedia(item.media);
  const merged = { ...item.previewProps, ...demo.props, ...props };
  // Swap in generated media unless the user typed their own value.
  for (const [name, url] of Object.entries(mediaUrls)) {
    if (merged[name] === item.defaults[name] || merged[name] === item.previewProps[name]) merged[name] = url;
  }
  const waitingForMedia = Object.keys(item.media).some(name => !mediaUrls[name]);
  const children = 'children' in demo ? demo.children ?? undefined : renderChildren(item.children, item.fill);

  let element = demo.render ? demo.render(Comp, merged, children) : <Comp {...merged}>{children}</Comp>;
  if (demo.wrap) element = demo.wrap(element);
  // Components that fill their parent (position: absolute; inset: 0) need a parent with height.
  // Text animations get a display-size base font: their demos size text with Tailwind classes.
  if (!item.fill) element = <div className={`rb-box ${item.category === 'text-animations' ? 'rb-text' : ''}`}>{element}</div>;
  // Reproduce a fixed-width wrapper from the usage snippet (e.g. <div style={{ width: 560 }}>).
  if (keepWrapper(item.wrapper)) {
    element = (
      <div className="rb-sized" style={{ width: '100%', ...item.wrapper, maxWidth: '100%' }}>
        {element}
      </div>
    );
  }

  return (
    <PreviewBoundary>
      <Suspense fallback={<div className="preview-loading">Generating terrain…</div>}>
        {waitingForMedia ? <div className="preview-loading">Recording demo media…</div> : element}
      </Suspense>
    </PreviewBoundary>
  );
}

// Applies the pixel-adventure demo content: controlled props become new defaults (and are
// written into the usage snippet); everything else only changes what the preview receives.
const LOCAL_MEDIA = /^\/(?!pixel\/|favicon)[^\s'"]+\.(png|jpe?g|webp|gif|svg|mp4|webm|mov|mp3|wav|ogg)$/i;

function hash(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619);
  return h >>> 0;
}

// Demo files that only exist on reactbits.dev become pixel art: images map to a biome postcard
// (stable per path), SVG logos to the gem favicon; video and audio are generated at runtime.
function localMedia(value, media, name) {
  if (typeof value === 'string' && LOCAL_MEDIA.test(value)) {
    const ext = value.split('.').pop().toLowerCase();
    if (['mp4', 'webm', 'mov'].includes(ext)) media[name] = 'video';
    else if (['mp3', 'wav', 'ogg'].includes(ext)) media[name] = 'audio';
    else if (ext === 'svg') return '/favicon.svg';
    else return `/pixel/biome-${BIOMES[hash(value) % BIOMES.length].id}.png`;
    return value;
  }
  if (Array.isArray(value)) return value.map(entry => localMedia(entry, {}, name));
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, localMedia(entry, {}, name)]));
  return value;
}

function themed(item) {
  const media = {};
  const defaults = Object.fromEntries(Object.entries(item.defaults).map(([name, value]) => [name, localMedia(value, media, name)]));
  const previewProps = Object.fromEntries(Object.entries(item.previewProps).map(([name, value]) => [name, localMedia(value, media, name)]));
  for (const [name, value] of Object.entries(THEMED_PROPS[item.name] ?? {})) {
    // Never feed an option-list prop a value outside its options (e.g. status enums).
    const control = item.controls.find(entry => entry.name === name);
    if (control?.type === 'select' && !control.options.includes(value)) continue;
    if (name in defaults && typeof value === typeof defaults[name]) defaults[name] = value;
    else previewProps[name] = value;
  }
  return {
    ...item,
    defaults,
    previewProps,
    media,
    usage: injectProps(item.usage, defaults, item.defaults),
    children: THEMED_CHILDREN[item.name] ? { text: THEMED_CHILDREN[item.name] } : item.children
  };
}

export const REACTBITS_ITEMS = data.items.map(themed).map(item => ({
  ...item,
  origin: 'reactbits',
  path: `/reactbits/${item.category}/${item.slug}`,
  file: `${item.name}/${item.entry}`,
  fullBleed: item.fill,
  originalUrl: `https://reactbits.dev/${item.category}/${item.slug}`,
  registryUrl: `https://reactbits.dev/r/${item.name}-JS-CSS.json`,
  render: props => <Preview item={item} props={props} />,
  loadSources: () =>
    Promise.all(
      [...item.files]
        .sort((a, b) => a.endsWith('.css') - b.endsWith('.css'))
        .map(file => sources[`../reactbits/${item.name}/${file}`]().then(code => ({ file, code })))
    )
}));
